package com.projeto.carrinhoPraiagp02;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.transaction.annotation.Transactional;
import com.projeto.carrinhoPraiagp02.models.*; import com.projeto.carrinhoPraiagp02.repository.*; import com.projeto.carrinhoPraiagp02.service.*;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class CarrinhoServiceIntegrationTest {
 @Autowired CarrinhoService service; @Autowired CheckoutService checkout; @Autowired PedidoService orderService; @Autowired VendasService salesService; @Autowired ProdutoRepo products; @Autowired CarrinhoRepo carts; @Autowired ComandaRepo comandas; @Autowired PedidoRepo orders; @Autowired PagamentoRepo payments; @Autowired VendasRepo sales; @Autowired MovimentacaoRepo movements;
 @Test void addCalculatesPriceAndRejectsStockOverflow(){Produto p=new Produto();p.setNome("Agua");p.setDescricao("");p.setPreco(new BigDecimal("3.50"));p.setQuantidadeEstoque(4);p.setEstoqueMinimo(1);p.setCategoria("Bebida");p.setDisponibilidade(true);products.save(p);comandas.save(new Comanda("T-001","Cliente"));var cart=service.criar("T-001");var result=service.adicionar(cart.getId(),cart.getAccessToken(),p.getId(),2);assertEquals(new BigDecimal("7.00"),result.getValorTotal());assertThrows(RuntimeException.class,()->service.adicionar(cart.getId(),cart.getAccessToken(),p.getId(),3));}
 private Produto product(int stock){Produto p=new Produto();p.setNome("Suco");p.setDescricao("");p.setPreco(new BigDecimal("8.00"));p.setQuantidadeEstoque(stock);p.setEstoqueMinimo(1);p.setCategoria("Bebida");p.setDisponibilidade(true);return products.save(p);}
 @Test void checkoutIsAtomicAndCancelRestoresOnlyOnce(){Produto p=product(5);comandas.save(new Comanda("C-100","Cliente"));Carrinho c=service.criar("C-100");service.adicionar(c.getId(),c.getAccessToken(),p.getId(),2);Pedido order=checkout.checkout(c.getId(),c.getAccessToken(),"PIX","test");assertEquals(3,products.findById(p.getId()).orElseThrow().getQuantidadeEstoque());assertEquals(1,orders.count());assertEquals(1,payments.count());assertEquals(1,sales.count());assertEquals(1,movements.count());assertTrue(carts.findById(c.getId()).orElseThrow().getItens().isEmpty());assertThrows(RuntimeException.class,()->checkout.checkout(c.getId(),c.getAccessToken(),"PIX","test"));assertThrows(RuntimeException.class,()->orderService.updateStatus(order.getId(),"CANCELADO"));checkout.cancel(order.getId(),"test");checkout.cancel(order.getId(),"test");assertEquals(5,products.findById(p.getId()).orElseThrow().getQuantidadeEstoque());assertEquals("CANCELADO",payments.findAll().get(0).getStatus());assertTrue(salesService.all().isEmpty());assertEquals(2,movements.count());}
 @Test void insufficientStockDoesNotCreateAnyCheckoutRecords(){Produto p=product(1);comandas.save(new Comanda("C-101","Cliente"));Carrinho c=service.criar("C-101");service.adicionar(c.getId(),c.getAccessToken(),p.getId(),1);p.ajustarEstoque(0);products.save(p);assertThrows(RuntimeException.class,()->checkout.checkout(c.getId(),c.getAccessToken(),"DINHEIRO","test"));assertEquals(0,orders.count());assertEquals(0,payments.count());assertEquals(0,sales.count());assertTrue(carts.findById(c.getId()).orElseThrow().getItens().size()==1);}
}
